import React, { useState, useEffect } from 'react';

const ProductReviews = ({ productId, productTitle }) => {
  const [reviews, setReviews] = useState([]);

  useEffect(() => {
    const fetchReviews = () => {
      const allReviews = JSON.parse(localStorage.getItem('productReviews')) || [];
      
      // Match by ID or by matching product name/title if available
      const matched = allReviews.filter((r) => {
        const matchId = r.productId && productId && String(r.productId).trim() === String(productId).trim();
        const matchTitle = r.productTitle && productTitle && String(r.productTitle).toLowerCase() === String(productTitle).toLowerCase();
        return matchId || matchTitle;
      });

      setReviews(matched);
    };

    fetchReviews();
    window.addEventListener('storage', fetchReviews);
    return () => window.removeEventListener('storage', fetchReviews);
  }, [productId, productTitle]);

  const avgRating = reviews.length > 0
    ? (reviews.reduce((acc, r) => acc + Number(r.rating || 0), 0) / reviews.length).toFixed(1)
    : null;

  return (
    <div style={{ marginTop: '20px', paddingTop: '16px', borderTop: '2px solid #e2e8f0', backgroundColor: '#fff', padding: '20px', borderRadius: '12px' }}>
      
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '14px' }}>
        <h3 style={{ margin: 0, fontSize: '16px', fontWeight: '800', color: '#0f172a' }}>
          Customer Reviews & Ratings ({productReviews ? productReviews.length : 0})
        </h3>
        {avgRating && (
          <span style={{ backgroundColor: '#fef3c7', color: '#92400e', padding: '4px 10px', borderRadius: '12px', fontSize: '13px', fontWeight: 'bold' }}>
            ★ {avgRating} / 5.0
          </span>
        )}
      </div>

      {reviews.length === 0 ? (
        <p style={{ margin: 0, fontSize: '13px', color: '#64748b', fontStyle: 'italic' }}>
          No reviews submitted yet for this product.
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {reviews.map((rev, idx) => (
            <div key={idx} style={{ backgroundColor: '#f8fafc', padding: '14px', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                <span style={{ color: '#f59e0b', fontSize: '14px', fontWeight: 'bold' }}>
                  {'★'.repeat(rev.rating)}{'☆'.repeat(5 - rev.rating)}
                </span>
                {rev.title && <strong style={{ fontSize: '14px', color: '#0f172a' }}>{rev.title}</strong>}
              </div>
              <p style={{ margin: '4px 0', fontSize: '13px', color: '#334155', lineHeight: '1.4' }}>
                "{rev.description}"
              </p>
              {rev.image && (
                <img src={rev.image} alt="Review attachment" style={{ width: '60px', height: '60px', objectFit: 'cover', borderRadius: '6px', marginTop: '6px' }} />
              )}
              <span style={{ fontSize: '11px', color: '#94a3b8', display: 'block', marginTop: '6px' }}>
                {rev.date || 'Verified Buyer'}
              </span>
            </div>
          ))}
        </div>
      )}

    </div>
  );
};

export default ProductReviews;
